import type { PinselaTemplateDocV1 } from "../core/types";
import announcement from "./builtin/post-announcement.json";
import story from "./builtin/story-event.json";
import carousel from "./builtin/carousel-tips.json";
import quote from "./builtin/quote.json";
import invitation from "./builtin/invitation.json";
import banner from "./builtin/banner-promo.json";

export type BuiltinTemplate = {
  id: string;
  name: string;
  description: string;
  doc_json: PinselaTemplateDocV1;
};

// Generated by generateBuiltin.ts (shapes, gradients and text only; bundled OFL fonts).
export const BUILTIN_TEMPLATES: BuiltinTemplate[] = [announcement, story, carousel, quote, invitation, banner] as unknown as BuiltinTemplate[];

export function builtinTemplateFormat(template: BuiltinTemplate): string {
  const { width, height } = template.doc_json.canvas;
  return `${Math.round(width)} × ${Math.round(height)}`;
}

export function builtinTemplatePageCount(template: BuiltinTemplate): number {
  const meta = template.doc_json.metadata as Record<string, any> | undefined;
  const pages = meta?.project_pages_v1?.pages;
  return Array.isArray(pages) ? pages.length : 1;
}
